import{_ as o,a as r,b as a,c as i,d as n,e as s,f as d,g as l}from"./chunks/stroke_stroke_over_fill.Bi6zz1iX.js";import{b as h,a as c,_ as g,c as p,d as u}from"./chunks/gradient_crayon.DE4cwuu8.js";import{_ as f,a as m,b}from"./chunks/bounding_box.DUhxQAFs.js";import{_ as y,C as w,o as k,c as v,E as x,a2 as S}from"./chunks/framework.CkaEw-3u.js";const T="/mug-typography-docs/image/gradient_example.webp",D=JSON.parse('{"title":"Global Settings","description":"Text-wide transform, color, stroke, shadow, and bounding-box controls","frontmatter":{"title":"Global Settings","description":"Text-wide transform, color, stroke, shadow, and bounding-box controls","pageClass":"reference-page","head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/en/reference/reference-global-settings.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Global Settings | Mug Typography Manual"}],["meta",{"property":"og:description","content":"Text-wide transform, color, stroke, shadow, and bounding-box controls"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/en/reference/reference-global-settings.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"Global Settings | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"Text-wide transform, color, stroke, shadow, and bounding-box controls"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"en/reference/reference-global-settings.md","filePath":"en/reference/reference-global-settings.md"}'),P={name:"en/reference/reference-global-settings.md"};function O(C,t,F,_,R,B){const e=w("ReferenceOverview");return k(),v("div",null,[x(e,{eyebrow:"PARAMETER REFERENCE",title:"Global Settings",description:"Find the text-wide controls for typography, transforms, color, stroke, shadow, and backgrounds by purpose.",items:[{icon:"Aa",title:"Text",description:"Text, font, and typography",href:"#text-settings"},{icon:"↗",title:"Transform",description:"Position, rotation, and stretch",href:"#transform"},{icon:"◐",title:"Color",description:"Fill, transparency, and gradients",href:"#color-settings"},{icon:"◇",title:"Stroke",description:"Outline, gap, and joins",href:"#outline-stroke"},{icon:"◒",title:"Shadow",description:"Distance, angle, and color",href:"#shadow-settings"},{icon:"▣",title:"Background",description:"Borders, fills, and padding",href:"#bounding-box-settings"}]}),t[0]||(t[0]=S('<p><a id="page-global-settings"></a></p><p>This page configures Text Settings (text, font, typesetting, morph animation), the overall Transform, Color Settings (fill color and gradient), the outline (Stroke), drop shadow, and bounding box.</p><p><img src="'+o+'" alt="Global Settings (top)"></p><p><img src="'+r+'" alt="Global Settings (middle)"></p><p><img src="'+a+'" alt="Global Settings (bottom)"></p><h2 id="reset" tabindex="-1">Reset <a class="header-anchor" href="#reset" aria-label="Permalink to &quot;Reset&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><strong>Reset All Characters</strong></td><td>Resets Pos, Pivot, Scale, Stretch, Rotation, Margin After, Use Indiv Color, Color, Use Indiv Stroke, Stroke Width, Stroke Gap, and Stroke Color for all characters and parts to their default values.</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Reset only affects <strong>per-character and per-part individual settings</strong>. Global Settings (settings applied to the entire text) are not reset.</p></div><h2 id="text-settings" tabindex="-1">Text Settings <a class="header-anchor" href="#text-settings" aria-label="Permalink to &quot;Text Settings&quot;">​</a></h2><p>A group that configures the text content, font, and typesetting (alignment, spacing, and overall scale) together.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Text (from)</strong></td><td>Enter the text to be displayed. The <code>(from)</code> in the label indicates that this text also serves as the morph source during a morph animation. Max character limit depends on the selected preset (see &quot;<a href="#limitations">Limitations</a>&quot; in the Appendix). For multi-line input, please refer to the note below.</td><td><code>Sample Text!</code></td></tr><tr><td><strong>Font</strong></td><td>Select the font to use from the list.</td><td>-</td></tr><tr><td><strong>Font Identity</strong></td><td>A housekeeping parameter that stores the internal identity of the selected font. You normally never need to edit it. To use a different font on each instance node, deinstance it <strong>together with Font</strong> (deinstancing only one of them will not restore the correct font).</td><td>-</td></tr><tr><td><strong>Horizontal Alignment</strong></td><td>Select the horizontal text alignment (Left / Center / Right).</td><td><code>Center</code></td></tr><tr><td><strong>Vertical Alignment</strong></td><td>Select the vertical text alignment (Top / Center / Bottom / Baseline).<br>・<strong>Top</strong>: Aligns text relative to the top edge.<br>・<strong>Center</strong>: Aligns text relative to the center of the ink bounding box (the drawn area).<br>・<strong>Bottom</strong>: Aligns text relative to the bottom edge.<br>・<strong>Baseline</strong>: Aligns text relative to the text baseline (prevents vertical shifting when text content changes and stabilizes vertical morph animation).</td><td><code>Center</code></td></tr><tr><td><strong>Vertical Mode</strong></td><td>When turned ON, text is written vertically.</td><td>OFF</td></tr><tr><td><strong>Tracking</strong></td><td>Specifies the global character spacing applied uniformly to all characters, in em units. Positive values widen spacing; negative values narrow it. This value is summed with each character&#39;s individual Margin After.</td><td><code>0.0</code></td></tr><tr><td><strong>Line Spacing</strong></td><td>Specifies the line spacing for multi-line text, in em units (relative to font size).</td><td><code>1.0</code></td></tr><tr><td><strong>Scale</strong></td><td>Scales the entire text uniformly.</td><td><code>1.0</code></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Multi-line Text Input and Line Breaks</strong></p><ul><li><p><strong>Inputting on the Fusion Page:</strong> On the Fusion page, you can type newlines directly by pressing the Enter key to write multi-line text.</p></li><li><p><strong>Inputting on the Edit Page:</strong> Due to Edit page Inspector UI limitations, you cannot type Enter to create newlines directly in the text box. If you want to write multi-line text on the Edit page, insert <code>\\n</code> or <code>&lt;br&gt;</code> at the desired line break positions. These are automatically treated as line breaks.</p><p>Also note that on the Edit page, pressing Enter while typing may move focus to a different parameter instead of inserting a line break. Be careful not to press Enter unintentionally while typing.</p></li><li><p><strong>Escaping Line Breaks:</strong> If you want to render the literal characters <code>\\n</code> or <code>&lt;br&gt;</code> without breaking the line, prepend them with a backslash to escape them: <code>\\\\n</code> or <code>\\&lt;br&gt;</code>.</p></li></ul><table tabindex="0"><thead><tr><th>Input in the Text field</th><th>Rendered result</th></tr></thead><tbody><tr><td><code>あ\\nい</code></td><td>あ<br>い (rendered on two lines)</td></tr><tr><td><code>あ&lt;br&gt;い</code></td><td>あ<br>い (rendered on two lines)</td></tr><tr><td><code>あ\\\\nい</code></td><td>あ\\nい (escaped — no line break, shown as a single line)</td></tr><tr><td><code>あ\\&lt;br&gt;い</code></td><td>あ&lt;br&gt;い (escaped — no line break, shown as a single line)</td></tr></tbody></table></div><p><a id="morph-animation"></a></p><h3 id="morph-animation" tabindex="-1">Morph Animation <a class="header-anchor" href="#morph-animation" aria-label="Permalink to &quot;Morph Animation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Enable Morph</strong></td><td>Enables morph animation. When ON, the normal text rendering is replaced by a morph from Text (start) to To Text (end).</td><td>OFF</td></tr><tr><td><strong>To Text</strong></td><td>Enter the destination text the morph ends at. Multi-line is supported.</td><td>(empty)</td></tr><tr><td><strong>Progress</strong></td><td>Specifies the morph progress from <code>0.0</code> (= the Text state) to <code>1.0</code> (= the To Text state). <strong>Keyframe this value on the timeline</strong> to freely control the speed and timing of the morph. Easing is also adjusted via this keyframe curve.</td><td><code>0.0</code></td></tr><tr><td><strong>Matching Strength</strong></td><td>Specifies how strongly the morph refines its part pairings beyond simple spatial proximity. At <code>0.0</code>, parts are matched based purely on position (original behaviour). Higher values do two things: (1) they consider <strong>filled-area similarity</strong>, preferring to pair parts with similar painted area (e.g., avoiding a small dot pairing with a full stroke), and (2) they keep a character that has an individual color, stroke, or shadow paired with the character at the <strong>same position</strong> in the To Text, so its individual styling is not stranded onto an unrelated glyph.</td><td><code>0.3</code></td></tr><tr><td><strong>Same Glyph Priority</strong></td><td>Specifies the strength of pairing <strong>identical characters</strong> between the start and end texts. At <code>0.0</code>, characters match purely by position. At <code>1.0</code>, identical characters are always paired regardless of distance. Identical character pairs slide into place rather than changing shape, keeping the animation clean.</td><td><code>0.3</code></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Path Deformation effects (Pulse / Trapezoid / Sphere / Barrel) and the Hand Drawn effect can also be layered on top of the morph result.</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>You can morph <strong>even when the starting and ending texts have a different number of characters</strong> (excess characters automatically appear/disappear). However, texts with a similar number of characters and similar shape complexity (part count) morph more naturally and cleanly.</p></div><h2 id="transform" tabindex="-1">Transform <a class="header-anchor" href="#transform" aria-label="Permalink to &quot;Transform&quot;">​</a></h2><p>A group that configures the position, rotation, and stretch applied to the entire text at once.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Position</strong></td><td>Specifies the position of the entire text on the canvas. <code>0.5, 0.5</code> is the center of the canvas.</td><td><code>0.5, 0.5</code></td></tr><tr><td><strong>Pivot</strong></td><td>Specifies the pivot point for rotation and scaling on the canvas.</td><td><code>0.5, 0.5</code></td></tr><tr><td><strong>Rotation</strong></td><td>The rotation angle of the entire text (in degrees).</td><td><code>0°</code></td></tr><tr><td><strong>Stretch</strong></td><td>Scales the X and Y directions individually.</td><td><code>1.0, 1.0</code></td></tr></tbody></table><h3 id="_3d-scripting-presets-only" tabindex="-1">3D / Scripting Presets Only <a class="header-anchor" href="#_3d-scripting-presets-only" aria-label="Permalink to &quot;3D / Scripting Presets Only&quot;">​</a></h3><p>The 3D and Scripting presets also show these parameters in the Transform group.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td><strong>Global Yaw</strong></td><td>Tilts the entire text horizontally around the Global Pivot.</td><td style="text-align:right;"><code>0°</code></td></tr><tr><td><strong>Global Pitch</strong></td><td>Tilts the entire text vertically around the Global Pivot.</td><td style="text-align:right;"><code>0°</code></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The overall uniform scaling (Scale) is located in the Text Settings group. While Scale changes both X and Y simultaneously, Stretch modifies only one axis, which is useful for distorting text vertically or horizontally.</p></div><h2 id="color-settings" tabindex="-1">Color Settings <a class="header-anchor" href="#color-settings" aria-label="Permalink to &quot;Color Settings&quot;">​</a></h2><p>A group that configures the text fill color, transparent fill, and gradient together.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Font Color</strong></td><td>Specifies the base color (RGB + Opacity) for the entire text.</td><td>-</td></tr><tr><td><strong>Transparent Fill</strong></td><td>When turned ON, the text body (fill) is made fully transparent and only the outline (Stroke) is rendered. To create hollow text, use it with a Stroke Width greater than <code>0.0</code>. It does not apply to characters or parts that have an individual color (Use Indiv Color).</td><td>OFF</td></tr></tbody></table><p><img src="'+i+'" alt="Example of hollow text using Transparent Fill"><em>(Example of hollow text created by turning Transparent Fill ON and setting the Stroke Width / Gap.)</em></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The Edit page cannot set the alpha value (transparency) of color parameters. See &quot;<a href="/mug-typography-docs/en/reference/appendix.html#limitations">Limitations</a>&quot; in the appendix for details.</p></div><h3 id="gradient" tabindex="-1">Gradient <a class="header-anchor" href="#gradient" aria-label="Permalink to &quot;Gradient&quot;">​</a></h3><p>A subgroup within the Color Settings group. Applies a gradient to the entire text using Font Color as the start color. The gradient is enabled when Color Space is set to any value other than <code>None</code> (the only exception is <code>Crayon</code>, which draws scribble strokes instead of a gradient; see below).</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The gradient range is calculated from the <strong>bounding box (BB) encompassing all parts at their transformed positions</strong>. If any character or part is moved or scaled such that the BB changes, the gradient range shifts across all characters accordingly.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Color Space</strong></td><td>Selects the color interpolation mode for the gradient. <code>None</code> disables the gradient. <code>Okhsv</code> / <code>Okhsl</code> provide perceptually uniform, hue-preserving interpolation. <code>Oklab</code> interpolates in perceptual lightness space. <code>Linear RGB</code> uses linear RGB interpolation. <code>Crayon</code> is a special mode that, instead of a gradient, draws hand-scribbled strokes in the end color (Gradient End Color) over the normal fill (see below).</td><td><code>None</code></td></tr><tr><td><strong>Gradient End Color</strong></td><td>The end color of the gradient (RGB + Opacity). Font Color serves as the start color.</td><td>Orange (<code>#ff8000</code>, opaque)</td></tr><tr><td><strong>Midpoint</strong></td><td>The position of the 50/50 blend point between start and end colors (0.5 = equal split).</td><td><code>0.5</code></td></tr><tr><td><strong>Angle</strong></td><td>The gradient direction in degrees. 0° is left to right, 90° is top to bottom.</td><td><code>270°</code></td></tr><tr><td><strong>Start</strong></td><td>The gradient start position relative to the bounding box (0 = BB start, 1 = BB end).</td><td><code>0.2</code></td></tr><tr><td><strong>End</strong></td><td>The gradient end position relative to the bounding box (0 = BB start, 1 = BB end).</td><td><code>0.8</code></td></tr></tbody></table><p><img src="'+T+'" alt="Gradient example"></p><h5 id="differences-in-interpolation-by-color-space" tabindex="-1">Differences in Interpolation by Color Space <a class="header-anchor" href="#differences-in-interpolation-by-color-space" aria-label="Permalink to &quot;Differences in Interpolation by Color Space&quot;">​</a></h5><p>Even with the same two colors (start color <code>#0000FF</code> = blue, end color <code>#FFFF00</code> = yellow), the appearance of the intermediate colors differs greatly depending on the chosen Color Space. <code>Okhsv</code> / <code>Okhsl</code> travel along the hue wheel through vivid intermediate colors (cyan to green), <code>Oklab</code> keeps perceptually uniform lightness, and <code>Linear RGB</code> produces a muddy gray midpoint due to simple numeric interpolation.</p><table tabindex="0"><thead><tr><th>Color Space</th><th>Sample</th></tr></thead><tbody><tr><td><strong>Okhsv</strong></td><td><img src="'+h+'" alt="Okhsv"></td></tr><tr><td><strong>Okhsl</strong></td><td><img src="'+c+'" alt="Okhsl"></td></tr><tr><td><strong>Oklab</strong></td><td><img src="'+g+'" alt="Oklab"></td></tr><tr><td><strong>Linear RGB</strong></td><td><img src="'+p+'" alt="Linear RGB"></td></tr></tbody></table><p><a id="gradient-crayon"></a></p><h5 id="crayon-hand-scribbled-fill" tabindex="-1">Crayon (Hand-Scribbled Fill) <a class="header-anchor" href="#crayon-hand-scribbled-fill" aria-label="Permalink to &quot;Crayon (Hand-Scribbled Fill)&quot;">​</a></h5><p>When Color Space is set to <code>Crayon</code>, instead of applying a gradient, hand-drawn scribble strokes in the <strong>Gradient End Color</strong> are drawn over the normal fill (Font Color). This creates a texture that looks like the text was roughly colored in with a crayon or colored pencil.</p><p>In this mode, the gradient parameters are reinterpreted as follows:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Meaning in Crayon mode</th></tr></thead><tbody><tr><td><strong>Gradient End Color</strong></td><td>Color of the scribble strokes</td></tr><tr><td><strong>Angle</strong></td><td>Stroke direction</td></tr><tr><td><strong>Midpoint</strong></td><td>Spacing between strokes</td></tr><tr><td><strong>Start</strong></td><td>Stroke thickness</td></tr><tr><td><strong>End</strong></td><td>Outline overshoot and endpoint variation strength</td></tr></tbody></table><p>The strokes retain a strong bias toward the Angle direction while overlapping with varied pigment density and fine wax-like gaps. Increasing End adds small irregularities near the outline and makes occasional strokes extend farther beyond it.</p><p><img src="'+u+'" alt="Crayon mode example"></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>While Crayon is active, individual character and part shadow colors are disabled; only <strong>Draw Global Shadow</strong> and the global shadow color apply. Individual shadow settings are preserved and become effective again after switching to another Color Space.</p></div><h3 id="texture" tabindex="-1">Texture <a class="header-anchor" href="#texture" aria-label="Permalink to &quot;Texture&quot;">​</a></h3><p>A subgroup within Color Settings. It layers a built-in material over the fill to produce looks such as water droplets, an air cushion, glitter, iridescence, faceted surfaces, stained glass, and polished metal. <code>None</code> keeps the ordinary fill.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Texture</strong></td><td>Selects the material to use: <code>None</code> / <code>Water Droplet</code> / <code>Air Cushion</code> / <code>Glitter</code> / <code>Iridescent</code> / <code>Faceted</code> / <code>Stained Glass</code>. <strong>Not animated.</strong></td><td><code>None</code></td></tr><tr><td><strong>P1</strong> – <strong>P4</strong></td><td>Four controls shared by every material. Their meaning and displayed name follow the selected material (see the table below).</td><td><code>0.5</code></td></tr><tr><td><strong>Texture Color</strong></td><td>Sets the color of the material. What it applies to depends on the material: the metal flakes for <code>Glitter</code>, the lead for <code>Stained Glass</code>, and the added light for the rest. <code>Iridescent</code> ignores it.</td><td>White (<code>#ffffff</code>)</td></tr></tbody></table><h4 id="control-mapping-p1–p4" tabindex="-1">Control mapping (P1–P4) <a class="header-anchor" href="#control-mapping-p1–p4" aria-label="Permalink to &quot;Control mapping (P1–P4)&quot;">​</a></h4><p>The four controls are generic slots shared by every material, and their displayed names change with the selection.</p><table tabindex="0"><thead><tr><th>Texture</th><th>P1</th><th>P2</th><th>P3</th><th>P4</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>P1</td><td>P2</td><td>P3</td><td>P4</td></tr><tr><td><strong>Water Droplet</strong></td><td>Thickness (surface height)</td><td>Roundness (profile curvature)</td><td>Gloss (reflection strength and sharpness)</td><td>Light Angle (light direction)</td></tr><tr><td><strong>Air Cushion</strong></td><td>Inflation (bulge)</td><td>Seal Width (sealed edge width)</td><td>Wrinkles (surface creasing)</td><td>Light Angle (light direction)</td></tr><tr><td><strong>Glitter</strong></td><td>Flake Size</td><td>Highlight Ratio (share of lit flakes)</td><td>Flake Amount (number of flakes)</td><td>Light Angle (degrees)</td></tr><tr><td><strong>Iridescent</strong></td><td>Film Thickness</td><td>Hue Range (spread of hues)</td><td>Strength</td><td>Light Angle (light direction)</td></tr><tr><td><strong>Faceted</strong></td><td>Facets (number of faces)</td><td>Bevel Depth</td><td>Polish</td><td>Light Angle (light direction)</td></tr><tr><td><strong>Stained Glass</strong></td><td>Piece Size</td><td>Lead Width</td><td>Hue Range (spread of hues)</td><td>Glow (emission and dimming)</td></tr><tr><td><strong>Metallic</strong></td><td>Polish</td><td>Relief (surface undulation)</td><td>Reflection Contrast</td><td>Light Angle (light direction)</td></tr><tr><td><strong>Metallic 2</strong></td><td>Polish</td><td>Relief (surface undulation)</td><td>Exposure (brightness)</td><td>Light Angle (light direction)</td></tr></tbody></table><p>The displayed range and step change to suit the material: a Light Angle slot shows <code>0</code>–<code>360</code> degrees, and every other slot shows <code>0</code>–<code>1</code>. Switching materials never rewrites the stored values, so <strong>a value set for the previous material can remain out of range</strong> — a Light Angle of <code>270</code> left behind in a slot that now runs <code>0</code>–<code>1</code>, for instance. The material folds such a value into the range it can use, so values that wrap (such as an angle) repeat and values with a limit rest against it. If the result is not what you expected, set the controls again for the material you chose.</p><p>Light Angle rotates clockwise in screen space, with the original upper-left direction as 0 degrees. Lighting stays fixed in screen space as normals are adjusted for text rotation and reflection.</p><h4 id="what-each-material-looks-like" tabindex="-1">What each material looks like <a class="header-anchor" href="#what-each-material-looks-like" aria-label="Permalink to &quot;What each material looks like&quot;">​</a></h4><ul><li><strong>Water Droplet</strong> — Swells each part into a rounded, water-filled surface and lights it with highlights. Raising Gloss tightens the edges of the reflections, and bright reflections keep their gradation instead of collapsing into flat white where they overlap.</li><li><strong>Air Cushion</strong> — Looks like a film inflated with air, formed from a sealed edge that follows the outline and a raised chamber inside it. Raising Wrinkles creases the surface.</li><li><strong>Glitter</strong> — Dense angular metal flakes catch directional light. Each flake carries <strong>its own brightness</strong>, so dim flakes and burning-white ones are mixed together. Flakes also appear over the stroke.</li><li><strong>Iridescent</strong> — Rainbow colors from thin-film interference, with Hue Range setting how far the hue swings. <strong>Texture Color is ignored</strong>, because the colors come from the film itself.</li><li><strong>Faceted</strong> — Splits the surface into facets that catch the light at different angles. Every facet is tilted by the same amount, set by Bevel Depth.</li><li><strong>Stained Glass</strong> — Splits the fill into pieces of colored glass outlined with lead came. See below for details.</li><li><strong>Metallic</strong> — Treats the fill color as a metal&#39;s own reflectance and polishes it under a built-in studio light: ochre reads as gold, light gray as silver, red-brown as copper. Raising Polish moves it towards a mirror.</li><li><strong>Metallic 2</strong> — The same metal under brighter, higher-contrast lighting. Only P3 differs, becoming Exposure over the whole environment, while Polish and Relief keep their meaning. It ships as its own material because <strong>its look cannot be reached from Metallic by moving sliders</strong>.</li></ul><h4 id="glitter-in-detail" tabindex="-1">Glitter in detail <a class="header-anchor" href="#glitter-in-detail" aria-label="Permalink to &quot;Glitter in detail&quot;">​</a></h4><ul><li>Setting <strong>Flake Size</strong> to <code>0</code> does not make the flakes as fine as possible — <strong>the flakes disappear entirely.</strong> Raising it makes them larger and spaces them further apart.</li><li><strong>Highlight Ratio</strong> sets the share of lit flakes: <code>0</code> has no strong highlights, <code>1</code> lights every flake. Density and placement stay fixed.</li><li><strong>Flake Amount</strong> controls all flakes, including unlit ones: <code>0</code> removes flakes and glow, <code>1</code> keeps full density. Remaining flakes retain their positions, sizes and colours. Hue spread is fixed at the former Hue Range <code>1.0</code>.</li><li><strong>Light Angle</strong> rotates the light in degrees. Flakes stay fixed while their reflections change; animate it with keyframes.</li><li><strong>Texture Color</strong> sets the metal colour. The strongest reflections approach white.</li></ul><p>Lit flakes have a near-white core and a soft glow. Glow stays within the text outline and follows Highlight Ratio.</p><h4 id="stained-glass-in-detail" tabindex="-1">Stained Glass in detail <a class="header-anchor" href="#stained-glass-in-detail" aria-label="Permalink to &quot;Stained Glass in detail&quot;">​</a></h4><ul><li><strong>Piece Size</strong> is a ratio <strong>relative to the untransformed character size</strong>. <code>0</code>–<code>1</code> corresponds to roughly 8–60% of the longer side of the character&#39;s bounding box.</li><li>Setting <strong>Lead Width</strong> to <code>0</code> <strong>removes the lead</strong> and lets the pieces meet each other directly. The lead takes its color from <strong>Texture Color</strong>, so the default white produces white lead.</li><li><strong>Hue Range</strong> spreads each piece&#39;s hue up to ±180° × P3 from the hue of the fill. At <code>0</code> the pieces keep the fill&#39;s hue; at <code>1</code> every hue is allowed and the minimum saturation and brightness rise too, so <strong>even a gray fill becomes vividly multicolored</strong>.</li><li><strong>Glow</strong> is centered at <code>0.5</code>, which is plain glass. Raising it makes the pieces <strong>emit</strong>, spreading colored transmitted light and a soft shine through the inside of the character; lowering it <strong>drains the light</strong> out of them, like looking through a window into an unlit room. Dimming preserves the hue and the fill&#39;s opacity, so the glass never reads as an opaque black hole. The reflection direction is fixed.</li><li><strong>The division and each piece&#39;s color follow the character</strong> through scaling, rotation, yaw, and pitch.</li><li>Outline curves are straightened according to the size of each piece, so larger pieces look angular while smaller ones stay closer to the original curve. Tiny slivers are avoided, thin strokes keep a piece length suited to their width, and small separate parts are left whole rather than divided.</li></ul><h4 id="how-textures-interact-with-other-settings" tabindex="-1">How textures interact with other settings <a class="header-anchor" href="#how-textures-interact-with-other-settings" aria-label="Permalink to &quot;How textures interact with other settings&quot;">​</a></h4><p>A material does not replace the fill — it is layered <strong>on top of it</strong>. Font Color, the gradient, and individual character or part colors all stay visible underneath, so the color you choose affects the result. Glitter derives its metal colour from Texture Color; Stained Glass derives its glass hues from the underlying fill.</p><p>Color opacity applies as well, so a fainter fill produces a fainter material. Turning on <strong>Transparent Fill, however, removes the fill entirely and therefore the material with it</strong> (characters and parts using an individual color are exempt from Transparent Fill, so the material remains on those).</p><h4 id="preview-in-mt-sim" tabindex="-1">Preview in MT Sim <a class="header-anchor" href="#preview-in-mt-sim" aria-label="Permalink to &quot;Preview in MT Sim&quot;">​</a></h4><p>In the MT Sim preview (VSCode extension), textures are drawn as <strong>a simplified hint of the result</strong>. The choice of material and the effect of each control can be checked there, but the actual surface and shading are not reproduced. Always confirm the final appearance in the plugin itself.</p><h2 id="outline-stroke" tabindex="-1">Outline (Stroke) <a class="header-anchor" href="#outline-stroke" aria-label="Permalink to &quot;Outline (Stroke)&quot;">​</a></h2><p>Renders the outline (stroke) of the text glyphs. Useful when you want to keep text legible over busy backgrounds, or to give characters a bold, outlined look.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>To make the outline visible, first set <strong>Width</strong> to a value greater than <code>0.0</code>. The outline is not rendered while it remains at <code>0.0</code>.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Width</strong></td><td>Specifies the thickness of the outline as a ratio to the font size (e.g., <code>0.05</code> is about 5% of the character height). It does not scale with transform or stretch scaling. Setting it to <code>0.0</code> disables outline rendering.</td><td><code>0.0</code></td></tr><tr><td><strong>Gap</strong></td><td>Specifies the width of the gap between the fill and the outline (stroke) as a ratio to the font size. When set greater than <code>0.0</code>, the area between the text body and the outline is cut out, producing a three-layer &quot;detached outline&quot; look (body, gap, outline).</td><td><code>0.0</code></td></tr><tr><td><strong>Color</strong></td><td>Specifies the color of the outline (RGB + Opacity).</td><td>Off-black (<code>#1c1c1e</code>)</td></tr><tr><td><strong>Outer Width</strong></td><td>Specifies the outer outline thickness as a ratio to the font size. It renders independently when Width (Inner Stroke) is <code>0.0</code>, and Gap is then applied between the text fill and Outer Stroke.</td><td><code>0.0</code></td></tr><tr><td><strong>Outer Color</strong></td><td>Specifies the color of the outer outline (RGB + opacity).</td><td>Cool white (<code>#f2f2f7</code>)</td></tr><tr><td><strong>Order</strong></td><td>Specifies the draw order of the stroke and fill. <code>Fill Over Stroke</code> draws the fill on top of the stroke, so only the outer half of the stroke is visible, creating an outside-stroke effect. <code>Stroke Over Fill</code> draws the stroke on top of the fill, causing it to overlap the glyph and appear to bite inward. <code>Fill Over Stroke (Per Character)</code> produces the same stacking as <code>Fill Over Stroke</code>, but completes each character before starting the next.</td><td><code>Fill Over Stroke</code></td></tr><tr><td><strong>Join Style</strong></td><td>Specifies the join style for the corners of the stroke.<br>・<strong>Miter Clip</strong>: Miter join. Sharpens corners.<br>・<strong>Round</strong>: Rounds corners.<br>・<strong>Bevel</strong>: Flattens corners (beveling).<br>・<strong>Miter Round</strong>: Produces the same result as Miter Clip.<br>・<strong>Miter Bevel</strong>: Produces the same result as Miter Clip.</td><td><code>Miter Clip</code></td></tr><tr><td><strong>Miter Limit</strong></td><td>The limit value for corner sharpness in miter joins. Sharper angles result in longer miter lengths, and a corner past this limit is flattened. The limit itself still applies, but Join Style can no longer choose what happens once it is exceeded.</td><td><code>4.0</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The three miter styles are no longer distinct</p><p>Since v6.0a, <strong>Miter Clip, Miter Round and Miter Bevel</strong> all render as the same miter join, so choosing between them makes no difference (a corner past the miter limit is always flattened). Round and Bevel work as before. The two redundant entries are scheduled for removal in a future version.</p></div><h5 id="join-style-samples" tabindex="-1">Join Style Samples <a class="header-anchor" href="#join-style-samples" aria-label="Permalink to &quot;Join Style Samples&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Join Style</th><th>Sample</th></tr></thead><tbody><tr><td><strong>Miter</strong></td><td><img src="'+n+'" alt="Miter"></td></tr><tr><td><strong>Round</strong></td><td><img src="'+s+'" alt="Round"></td></tr><tr><td><strong>Bevel</strong></td><td><img src="'+d+'" alt="Bevel"></td></tr></tbody></table><h5 id="draw-order-order-samples" tabindex="-1">Draw Order (Order) Samples <a class="header-anchor" href="#draw-order-order-samples" aria-label="Permalink to &quot;Draw Order (Order) Samples&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Draw Order</th><th>Sample</th></tr></thead><tbody><tr><td><strong>Fill Over Stroke</strong></td><td><img src="'+f+'" alt="Fill Over Stroke"></td></tr><tr><td><strong>Stroke Over Fill</strong></td><td><img src="'+l+'" alt="Stroke Over Fill"></td></tr></tbody></table><p><code>Fill Over Stroke (Per Character)</code> differs from <code>Fill Over Stroke</code> only where characters overlap. Plain <code>Fill Over Stroke</code> draws every character&#39;s stroke first and then every character&#39;s fill, so an overlapping character can lay its stroke over the fill of the character in front of it. Per character, one character&#39;s stroke and fill are finished before the next character begins, so each character ends with its own stroke hidden under its own fill and the characters keep their front-to-back relationship. A later character&#39;s gap can no longer cut into an earlier one either. With a layout whose characters do not overlap, the two look identical. Frames with 3D projection enabled always draw per character.</p><h2 id="shadow-settings" tabindex="-1">Shadow Settings <a class="header-anchor" href="#shadow-settings" aria-label="Permalink to &quot;Shadow Settings&quot;">​</a></h2><p>Renders a drop shadow for the entire text. Useful when you want to make the text stand out from the background with a sense of depth, or to improve legibility.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Draw Global Shadow</strong></td><td>Enables the global drop shadow that renders a shadow for all characters. The parameters below are always visible, but they only take effect while this is ON.<br>※ A character with an individual shadow color (Use Indiv Shadow Color) set on the Character Settings page casts a shadow even when this global shadow is OFF.</td><td>OFF</td></tr><tr><td><strong>Distance</strong></td><td>Specifies the shadow offset distance as a percentage of the canvas shorter side (whichever of width/height is smaller).</td><td><code>1.0</code></td></tr><tr><td><strong>Angle</strong></td><td>Specifies the shadow direction in degrees. 0° is right, 90° is downward.</td><td><code>45°</code></td></tr><tr><td><strong>Color</strong></td><td>Specifies the shadow color (RGB + Opacity).</td><td>Blue (<code>#5555ff</code>, opaque)</td></tr></tbody></table><p><img src="'+m+'" alt="Shadow example"></p><h2 id="bounding-box-settings" tabindex="-1">Bounding Box Settings <a class="header-anchor" href="#bounding-box-settings" aria-label="Permalink to &quot;Bounding Box Settings&quot;">​</a></h2><p>Configures rendering and filling of the bounding box (background frame) surrounding the entire text. Useful when you want to add a backing bar behind subtitles, or frame the text to give it a lower-third / telop look.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The <strong>bounding box (BB)</strong> is the smallest rectangle that encloses all characters and parts. When you move characters or parts individually, the size and position of the BB updates accordingly.</p></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><strong>Draw Bounding Box</strong></td><td>Enables drawing of the bounding box background and borders. When turned ON, the following parameters appear.</td><td>OFF</td></tr><tr><td><strong>Top Edge / Bottom Edge / Left Edge / Right Edge</strong></td><td>Specifies whether to draw the top, bottom, left, and right edges individually.</td><td>ON (all edges)</td></tr><tr><td><strong>Border Width</strong></td><td>Specifies the border width as a percentage of the font size.</td><td><code>20.0</code></td></tr><tr><td><strong>Border Color</strong></td><td>Specifies the border color.</td><td>Red (<code>1, 0, 0, 1</code>)</td></tr><tr><td><strong>Fill Background</strong></td><td>Specifies whether to fill the inside of the box with the background color. When ON, the background is rendered behind the glyphs and Fill Color / Fill Opacity / Fill Offset appear.</td><td>OFF</td></tr><tr><td><strong>Fill Color</strong></td><td>Specifies the background fill color (RGB + opacity).</td><td>Light Purple (<code>1, 0.667, 1, 1</code>)</td></tr><tr><td><strong>Fill Opacity</strong></td><td>Specifies the opacity of the background fill (0.0 = completely transparent, 1.0 = completely opaque).</td><td><code>1.0</code></td></tr><tr><td><strong>Start Cap Style / End Cap Style</strong></td><td>Specifies the end cap style of the stroke when drawing open paths (e.g., L-shape with 3 or fewer edges). Options: <code>Butt</code> (flat), <code>Square</code> (square), <code>Round</code> (round), <code>Round Rev</code> (reversed round), <code>Triangle</code> (triangle), <code>Triangle Rev</code> (reversed triangle).</td><td><code>Butt</code></td></tr><tr><td><strong>Margin X / Margin Y</strong></td><td>Specifies the margin on the sides (X) and top/bottom (Y) as a percentage of the font size. Negative values can be used to draw the border inside the text boundary.</td><td><code>40.0</code></td></tr><tr><td><strong>Corner Radius</strong></td><td>Specifies the radius for rounding the bounding box corners as a percentage of the font size. It always applies to the background fill. For the border, it takes effect <strong>only when all of the Top / Bottom / Left / Right edges are ON</strong>; with any edge OFF, the border is drawn with square corners.</td><td><code>0.0</code></td></tr><tr><td><strong>Border Offset</strong></td><td>Offsets the border rectangle in the X / Y directions, as a percentage of the font size. The fill rectangle stays in place, letting you shift only the border for offset frame designs.</td><td><code>0.0, 0.0</code></td></tr><tr><td><strong>Fill Offset</strong></td><td>Offsets the background fill rectangle in the X / Y directions, as a percentage of the font size. The border stays in place, letting you shift only the background.</td><td><code>0.0, 0.0</code></td></tr></tbody></table><p><img src="'+b+'" alt="Bounding box example (all edges, fill, and corner radius enabled)"></p><hr>',85))])}const M=y(P,[["render",O]]);export{D as __pageData,M as default};
